class _WalletHomeInsights extends StatelessWidget {
  const _WalletHomeInsights({
    required this.colors,
    required this.currencyFmt,
    required this.totalFiat,
    required this.chartDeltaFiat,
    required this.chartDeltaPercent,
    required this.allocation,
    required this.topMover,
    required this.topMoverFiat,
    required this.topMoverChange,
  });

  final AppColor colors;
  final NumberFormat currencyFmt;
  final double totalFiat;
  final double chartDeltaFiat;
  final double chartDeltaPercent;
  final _AllocationSnapshot? allocation;
  final AssetModel? topMover;
  final double topMoverFiat;
  final double topMoverChange;

  @override
  Widget build(BuildContext context) {
    final isPositive = chartDeltaFiat >= 0;
    final moverPositive = topMoverChange >= 0;
    return LayoutBuilder(
      builder: (context, constraints) {
        final isCompact = constraints.maxWidth < 860;
        final cards = <Widget>[
          _InsightCard(
            colors: colors,
            eyebrow: 'Portfolio pulse',
            title: isPositive ? 'Up this window' : 'Cooling off',
            value: currencyFmt.format(chartDeltaFiat.abs()),
            subtitle: chartDeltaPercent == 0
                ? 'No meaningful change yet'
                : '${isPositive ? '+' : '-'}${chartDeltaPercent.abs().toStringAsFixed(2)}% vs start',
            accentColor: isPositive ? colors.success : colors.warning,
            icon: isPositive ? LucideIcons.trendingUp : LucideIcons.trendingDown,
          ),
          _InsightCard(
            colors: colors,
            eyebrow: 'Largest allocation',
            title:
                allocation?.asset.symbol.toUpperCase() ?? 'Waiting for assets',
            value: allocation == null
                ? currencyFmt.format(totalFiat)
                : '${allocation!.sharePercent.toStringAsFixed(0)}%',
            subtitle: allocation == null
                ? 'Add funds to unlock allocation insights'
                : currencyFmt.format(allocation!.fiatValue),
            accentColor: colors.primary,
            icon: LucideIcons.pieChart,
          ),
          _InsightCard(
            colors: colors,
            eyebrow: 'Top mover',
            title: topMover?.symbol.toUpperCase() ?? 'Stable mix',
            value: topMover == null
                ? currencyFmt.format(totalFiat)
                : '${moverPositive ? '+' : '-'}${topMoverChange.abs().toStringAsFixed(2)}%',
            subtitle: topMover == null
                ? 'No active market move yet'
                : currencyFmt.format(topMoverFiat),
            accentColor: moverPositive ? colors.success : colors.error,
            icon: LucideIcons.activity,
          ),
        ];

        if (isCompact) {
          return Column(
            children: [
              for (var i = 0; i < cards.length; i++) ...[
                cards[i],
                if (i != cards.length - 1) const SizedBox(height: 12),
              ],
            ],
          );
        }

        return Row(
          children: [
            for (var i = 0; i < cards.length; i++) ...[
              Expanded(child: cards[i]),
              if (i != cards.length - 1) const SizedBox(width: 12),
            ],
          ],
        );
      },
    );
  }
}

class _QuickActionChip extends StatelessWidget {
  const _QuickActionChip({
    required this.label,
    required this.icon,
    required this.colors,
    required this.onTap,
    this.badge,
  });

  final String label;
  final IconData icon;
  final AppColor colors;
  final Future<void> Function()? onTap;
  final String? badge;

  @override
  Widget build(BuildContext context) {
    return Material(
      color: colors.surfaceRaised,
      borderRadius: BorderRadius.circular(18),
      child: InkWell(
        borderRadius: BorderRadius.circular(18),
        onTap: onTap == null ? null : () => unawaited(onTap!()),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Container(
                width: 30,
                height: 30,
                decoration: BoxDecoration(
                  color: colors.primary.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Icon(icon, size: 16, color: colors.primary),
              ),
              const SizedBox(width: 10),
              Text(
                label,
                style: TextStyle(
                  color: colors.textPrimary,
                  fontWeight: FontWeight.w700,
                ),
              ),
              if (badge != null) ...[
                const SizedBox(width: 8),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: colors.primary,
                    borderRadius: BorderRadius.circular(999),
                  ),
                  child: Text(
                    badge!,
                    style: TextStyle(
                      color: colors.onPrimary,
                      fontSize: 11,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }
}

class _InsightCard extends StatelessWidget {
  const _InsightCard({
    required this.colors,
    required this.eyebrow,
    required this.title,
    required this.value,
    required this.subtitle,
    required this.accentColor,
    required this.icon,
  });

  final AppColor colors;
  final String eyebrow;
  final String title;
  final String value;
  final String subtitle;
  final Color accentColor;
  final IconData icon;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: BoxDecoration(
        color: colors.surface,
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: colors.border),
      ),
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              width: 34,
              height: 34,
              decoration: BoxDecoration(
                color: accentColor.withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(12),
              ),
              child: Icon(icon, size: 17, color: accentColor),
            ),
            const SizedBox(height: 12),
            Text(
              eyebrow,
              style: TextStyle(
                color: colors.textMuted,
                fontSize: 11,
                fontWeight: FontWeight.w700,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              title,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: colors.textPrimary,
                fontSize: 14,
                fontWeight: FontWeight.w800,
              ),
            ),
            const SizedBox(height: 10),
            Text(
              value,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: colors.textPrimary,
                fontSize: 18,
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 6),
            Text(
              subtitle,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: colors.textSecondary,
                fontSize: 12,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

